import assert from "node:assert/strict";
import test from "node:test";

import { formatSize } from "../src/lib/format.js";
import {
  naturalCompare,
  normalizeName,
  normalizeRelativePath,
  normalizeStorageName,
} from "../src/lib/paths.js";
import {
  generatePasswordHash,
  verifyPassword,
} from "../src/lib/password.js";
import { signToken, verifyToken } from "../src/lib/tokens.js";

// Generated by werkzeug.security.generate_password_hash("Test123!").
const WERKZEUG_HASH =
  "scrypt:32768:8:1$WqUiMOWLcwt2RrSH$6404e8ec2e9d8ccfa9fa8aae12cb1de60e2f580956490bcb13addb732c005c578cc83451a165f17e2ee8214d876946ef6364dcdde3a573c7ba69680479d85e80";

test("verifies werkzeug scrypt hashes", () => {
  assert.equal(verifyPassword(WERKZEUG_HASH, "Test123!"), true);
  assert.equal(verifyPassword(WERKZEUG_HASH, "wrong"), false);
  assert.equal(verifyPassword("not-a-hash", "Test123!"), false);
});

test("generates hashes that verify", () => {
  const hash = generatePasswordHash("AnotherPass1!");
  assert.match(hash, /^scrypt:32768:8:1\$/);
  assert.equal(verifyPassword(hash, "AnotherPass1!"), true);
  assert.equal(verifyPassword(hash, "AnotherPass1"), false);
});

test("normalizes relative paths and blocks traversal", () => {
  assert.equal(normalizeRelativePath("a/./b"), "a/b");
  assert.equal(normalizeRelativePath("a\\\\b"), "a/b");
  assert.equal(normalizeRelativePath(""), "");
  assert.throws(() => normalizeRelativePath("../etc"), /parent traversal/);
  assert.throws(() => normalizeRelativePath("/etc/passwd"), /absolute paths/);
});

test("rejects unsafe names", () => {
  assert.equal(normalizeName("  report  "), "report");
  assert.throws(() => normalizeName("a/b"), /invalid name/);
  assert.equal(normalizeStorageName("101班"), "101班");
  assert.throws(() => normalizeStorageName(".."), /invalid storage name/);
});

test("formats sizes like the legacy service", () => {
  assert.equal(formatSize(0), "0 B");
  assert.equal(formatSize(1023), "1023 B");
  assert.equal(formatSize(1024), "1.0 KB");
  assert.equal(formatSize(1536), "1.5 KB");
  assert.equal(formatSize(1024 * 1024), "1.0 MB");
});

test("sorts file names naturally", () => {
  const names = ["a10", "a2", "a1"];
  names.sort(naturalCompare);
  assert.deepEqual(names, ["a1", "a2", "a10"]);
});

test("signs and verifies short-lived tokens", () => {
  const token = signToken({ purpose: "download", user_id: 7 });
  const payload = verifyToken(token, 300);
  assert.equal(payload.user_id, 7);
  assert.equal(payload.purpose, "download");
  assert.equal(verifyToken(`${token}x`, 300), null);
  assert.equal(verifyToken(token, -1), null);
});
